// ==========================================================
//  发音人分配规则（核心）：
//    双引号以内的文字  →  用 VV 朗读
//    双引号以外的文字  →  用温柔桃子朗读
//  最后把多段音频合并成一个返回。
// ==========================================================

// ---------- 1. 基础参数 ----------
var BASE_URL     = 'wss://audio5-normal-hl.myparallelstory.com/internal/api/v1/ws';
var AUDIO_FORMAT = 'mp3';
var SAMPLE_RATE  = 24000;
var APP_KEY      = 'WQuVLKMGRo';
var TIMEOUT_MS   = 30000;
var PITCH_VALUE  = 0;

// ---------- 2. 语速（固定值，直接改这里） ----------
var SPEED_BOOST = 1.15;   // 最终语速倍率
var rate = SPEED_BOOST;

// ---------- 3. 发音人与提示词 ----------
var VOICE_NARRATOR = 'zh_female_wenroutaozi_uranus_bigtts';  // 旁白：温柔桃子
var VOICE_DIALOG   = 'zh_female_vv_uranus_bigtts';           // 对话：VV
var PROMPT_NARRATOR = '男性旁白朗读';                         // 桃子提示词
var PROMPT_DIALOG   = '用夹子音朗读';                         // VV提示词

// ---------- 4. 按中文双引号拆分 ----------
var segments = [];
var text = speakText;
var idx = 0;

while (idx < text.length) {
    var qStart = text.indexOf('“', idx);
    if (qStart === -1) {
        // 后面全是旁白（无引号）→ 桃子
        if (idx < text.length) {
            segments.push({txt: text.substring(idx), voice: VOICE_NARRATOR});
        }
        break;
    }
    // qStart 之前的文字 → 旁白 → 桃子
    if (qStart > idx) {
        segments.push({txt: text.substring(idx, qStart), voice: VOICE_NARRATOR});
    }
    // 找对应的右双引号
    var qEnd = text.indexOf('”', qStart + 1);
    if (qEnd === -1) qEnd = text.length - 1;
    // 引号内（含引号本身）→ 对话 → VV
    segments.push({txt: text.substring(qStart, qEnd + 1), voice: VOICE_DIALOG});
    idx = qEnd + 1;
}

if (segments.length === 0) {
    segments.push({txt: text, voice: VOICE_NARRATOR});
}

// ---------- 5. 随机设备参数（防封） ----------
var deviceId = String(Math.floor(1e12 + 9e12 * Math.random()));
var aid      = String(Math.floor(1e12 + 9e12 * Math.random()));

// ---------- 6. 分别合成并合并 ----------
var out = ws.newBuffer();

for (var i = 0; i < segments.length; i++) {
    var seg = segments[i];
    if (!seg.txt || seg.txt.length === 0) continue;

    var query = 'voice=' + seg.voice + '&format=' + AUDIO_FORMAT + '&sampleRate=' + SAMPLE_RATE + '&appkey=' + APP_KEY;
    var wsUrl = BASE_URL + '?' + query + '&ssmix=&aid=' + aid + '&device_id=' + deviceId;

    var prompt = (seg.voice === VOICE_NARRATOR) ? PROMPT_NARRATOR : PROMPT_DIALOG;
    // extraPayload 是通用 JSON 字符串，可包含任意字段，自动合并到 API payload
    var extra = prompt ? '{"context_texts":["' + prompt + '"]}' : null;
    var audio = ws.maoxiang(wsUrl, seg.txt, seg.voice, AUDIO_FORMAT, SAMPLE_RATE, rate, PITCH_VALUE, APP_KEY, TIMEOUT_MS, extra);
    if (audio && audio.length > 0) {
        out.write(audio);
    }
}

// ---------- 7. 返回合并音频 ----------
out.toByteArray();
